query UsersConnection($first: Int, $after: String) {
  usersConnection(first: $first, after: $after) {
    edges {
      cursor
      node {
        id
        email
        role
      }
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
    }
    totalCount
  }
}

